package com.finsightai.controller;import com.finsightai.model.Transaction;import com.finsightai.service.*;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.time.LocalDate;import java.util.*;@RestController @RequestMapping("/api/transactions") public class TransactionController{private final TransactionService service;private final CsvImportService importer;public TransactionController(TransactionService s,CsvImportService i){service=s;importer=i;}@GetMapping public List<Transaction> search(@RequestParam(required=false)String q,@RequestParam(required=false)String type,@RequestParam(required=false)String category,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){return service.search(q,type,category,from,to);}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','FINANCE_ANALYST')")public Transaction create(@Valid @RequestBody Transaction t){return service.create(t);}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','FINANCE_ANALYST')")public Transaction update(@PathVariable Long id,@Valid @RequestBody Transaction t){return service.update(id,t);}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}@PostMapping("/import")@PreAuthorize("hasAnyRole('ADMIN','FINANCE_ANALYST')")public Map<String,Object> importCsv(@RequestParam MultipartFile file)throws IOException{return Map.of("imported",importer.importFile(file));}}
